        _ok_font = _n("Times New Roman\nĐiều 1. Phạm vi") == "điều 1. phạm vi"  # dòng font-run bị lọc
        _ok_keep = "theo times" in _n("Theo Times báo cáo")                   # câu THẬT chứa tên font: GIỮ
