                             {"text": "QUY ĐỊNH CHUNG", "de_muc": True, "kieu": "giua"},
                             {"text": "Mục 1. NGUYÊN TẮC", "de_muc": True, "kieu": "giua"},
                             {"text": "Điều 1. Phạm vi", "de_muc": True},
