    # ═══ v1.34.87 — r156: PHIẾU TRÌNH (biểu mẫu nội bộ Ủy ban, user nạp mẫu VHXH 20-07). Mẫu gốc có
    # 3 bảng TRÀN lề (9180/10065/9180 > vùng chữ 9072) ⇒ bộ dựng phải TÍNH bề rộng từ lề (§6.10). ═══
    def _c156_phieu_trinh():
        import re as _r6, zipfile as _z6, tempfile as _tf6
        SPEC = {"mau": "phieu_trinh", "chu_quan": "QUỐC HỘI KHÓA XVI",
                "ten_cq": "ỦY BAN VĂN HÓA VÀ XÃ HỘI",
                "dia_danh": "Hà Nội, ngày 20 tháng 7 năm 2026",
                "kinh_gui": "Đồng chí Chủ nhiệm Ủy ban", "noi_dung": "Tham gia ý kiến …",
                "qua_trinh": ["Thường trực Ủy ban nhận được Công văn số …"],
                "de_xuat": ["Kính trình đồng chí Chủ nhiệm xem xét, chỉ đạo."],
                "ky_trai": [{"chuc_vu": "Chuyên viên", "ho_ten": "Nguyễn Văn A"},
                            {"chuc_vu": "Phó Vụ trưởng", "ho_ten": "Trần Thị B"}],
                "y_kien_phai": ["Ý kiến của", "Chủ nhiệm Ủy ban"],
                "tong_hop": [{"ho_ten": "Lê Văn C (Phó Chủ nhiệm)", "dong_y": True,
                              "gop_y": "(không có ý kiến khác)"},
                             {"ho_ten": "UV Phạm Thị D", "dong_y": False, "gop_y": "Đề nghị viết gọn."}]}
        _o = str(Path(_tf6.mkdtemp()) / "pt.docx")
        env = _TL_MODULE.the_thuc_build(SPEC, _o)      # dispatch qua khoá spec "mau"
        if env.get("schema") != "phieu_trinh_build.v1" or env["self_check"]["fail"]:
            return False
        _x = _z6.ZipFile(_o).read("word/document.xml").decode("utf-8")
        _W = 11906 - 1701 - 1134
        # MỌI bảng phải nằm trong vùng chữ (lỗi thật của mẫu gốc)
        if [int(w) for w in _r6.findall(r'<w:tblW w:w="(\d+)"', _x)] != [_W, _W, _W]:
            return False
        # r157: bảng TIÊU ĐỀ không viền · bảng NỘI DUNG và bảng TỔNG HỢP đều CÓ viền.
        # (mẫu gốc mang viền qua <w:tblStyle TableGrid> trong styles.xml chứ không phải
        # <w:tblBorders> trực tiếp — soi thiếu chỗ này sẽ dựng ra bảng nội dung KHÔNG viền.)
        _tbls = _r6.findall(r"<w:tbl>.*?</w:tbl>", _x, _r6.S)
        if len(_tbls) != 3:
            return False
        # phải soi ĐÚNG thẻ viền: 'w:val="single"' trơn còn khớp cả <w:u w:val="single"/> (GẠCH
        # dưới tên cơ quan/Tiêu ngữ ở bảng tiêu đề) ⇒ bảng 1 bị coi nhầm là có viền.
        _co_vien = [('<w:top w:val="single"' in _t) for _t in _tbls]
        if _co_vien != [False, True, True]:
            return False
        # r158: bảng nội dung phải có 1 dòng nội dung + MỖI CẤP KÝ MỘT DÒNG (đúng mẫu gốc 4 dòng),
        # ô phải vMerge dọc suốt. Gộp các cấp ký chung một ô thì KHÔNG có viền ngăn giữa họ.
        _rows2 = _r6.findall(r"<w:tr>.*?</w:tr>", _tbls[1], _r6.S)
        if len(_rows2) != 1 + len(SPEC["ky_trai"]):
            return False
        if '<w:vMerge w:val="restart"/>' not in _rows2[0]:
            return False
        if not all("<w:vMerge/>" in _q for _q in _rows2[1:]):
            return False
        # MỌI ô của bảng nội dung đều có viền (kể cả các ô ký bên trái)
        for _q in _rows2:
            for _c in _r6.findall(r"<w:tc>.*?</w:tc>", _q, _r6.S):
                _bd = _r6.search(r"<w:tcBorders>.*?</w:tcBorders>", _c, _r6.S)
                if not _bd or 'w:val="single"' not in _bd.group(0):
                    return False
        # r159: "Kính gửi" KHÔNG đậm (user 20-07, khác mẫu gốc) · đề mục + paragraph TRONG BẢNG
        # thụt 0,8cm = 454tw (ưu tiên của user; NĐ30 cho 1-1,27cm nhưng đây là biểu mẫu nội bộ).
        def _para(_pred):
            for _q in _r6.findall(r"<w:p>.*?</w:p>", _x, _r6.S):
                _t = "".join(_r6.findall(r"<w:t[^>]*>([^<]*)</w:t>", _q)).strip()
                if _pred(_t):
                    return _q
            return ""
        _kg = _para(lambda t: t.startswith("Kính gửi:"))
        if not _kg or "<w:b/>" in _kg:
            return False
        for _pfx in ("Quá trình thực hiện:", "Đề xuất:", "Thường trực Ủy ban"):
            _q = _para(lambda t, _p=_pfx: t.startswith(_p))
            # r169: KHÔNG neo vào '<w:ind w:firstLine' — thẻ ind nay có thêm w:left phía trước.
            # Bẫy thứ tự thuộc tính (đã gặp với w:val của viền, và với bản Google-export).
            _m = _r6.search(r'w:firstLine="(\d+)"', _q)
            if not _m or int(_m.group(1)) != 454:
                return False
        # r160: ô CÓ VIỀN phải có đệm dọc, nếu không dòng cuối DÍNH nét kẻ dưới (user 20-07 gửi
        # ảnh). tblCellMar mặc định chỉ có trái/phải ⇒ phải khai thêm top/bottom. Bảng tiêu đề
        # (không viền, layout đã tinh chỉnh) giữ 0.
        def _mar(_t):
            _m = _r6.search(r"<w:tblCellMar>.*?</w:tblCellMar>", _t, _r6.S)
            _tp = _r6.search(r'<w:top w:w="(\d+)"', _m.group(0)) if _m else None
            _bt = _r6.search(r'<w:bottom w:w="(\d+)"', _m.group(0)) if _m else None
            return (int(_tp.group(1)) if _tp else 0, int(_bt.group(1)) if _bt else 0)
        if _mar(_tbls[0]) != (0, 0):
            return False
        if _mar(_tbls[1]) != (80, 80) or _mar(_tbls[2]) != (80, 80):   # r164: 6pt → 4pt
            return False
        # r161: Google Docs BỎ tblCellMar khi chuyển .docx → GDoc (kho mẫu lưu canonical dạng GDoc)
        # ⇒ đoạn CUỐI của ô có viền phải mang w:after (spacing SỐNG SÓT round-trip), nếu không bản
        # trên Drive lại dính nét kẻ dưới dù bản local đã đúng.
        for _t in (_tbls[1], _tbls[2]):
            for _c in _r6.findall(r"<w:tc>.*?</w:tc>", _t, _r6.S):
                _ps = _r6.findall(r"<w:p>.*?</w:p>", _c, _r6.S)
                if not _ps:
                    continue
                _last = _ps[-1]
                if not "".join(_r6.findall(r"<w:t[^>]*>([^<]*)</w:t>", _last)).strip():
                    continue          # ô vMerge rỗng — bỏ qua
                _af = _r6.search(r'w:after="(\d+)"', _last)
                if not _af or int(_af.group(1)) != 80:
                    return False
        _txt = "".join(_r6.findall(r'<w:t[^>]*>([^<]*)</w:t>', _x))
        return ("PHIẾU TRÌNH VĂN BẢN" in _txt and "TỔNG HỢP Ý KIẾN" in _txt
                and "Kính gửi: Đồng chí Chủ nhiệm Ủy ban" in _txt
                and "Quá trình thực hiện:" in _txt and "Đề xuất:" in _txt)
