        gb = _imp("gws_bridge")
        sp, seen = _fake_sp327(auth_cost=25.0)
        d = _avail327(gb, sp, {"TL_GWS_AUTH_TIMEOUT": "10"})      # đè hẳn, kể cả HẠ dưới mặc định
        okA = d.get("ok") is False and dict(seen).get("auth") == 10.0
