        _osp, _oexe = gb.subprocess, gb.gws_exe
        try:
            gb.subprocess, gb.gws_exe = sp, (lambda: "/fake/gws")
            with _env330(env):
                return fn()
        finally:
            gb.subprocess, gb.gws_exe = _osp, _oexe

