    # ═══ r261 — CỬA MONKEYPATCH ĐÚNG (bắt được khi gate deploy treo 580s) ═══
    # `tl.py` cài STUB uỷ quyền VĨNH VIỄN: `def _stub(*a, **k): return getattr(_mod, _name)(*a, **k)`
    # với `_mod` = submodule `tl_core.<x>`. Nên gán `_TL_MODULE.<tên> = fake` KHÔNG có tác dụng cho mọi
    # tên nằm trong `_STUB_MAP` — stub vẫn tra thuộc tính trên SUBMODULE và gọi hàm THẬT.
    # Đường `import tl; tl.selftest()` che mất lỗi này (khi đó dict mà hàm tra TRÙNG `_TL_MODULE`);
    # đường CHUẨN `python scripts/tl.py --selftest` thì lộ: `_rasoat_expand_text` fake bị bỏ qua ⇒
    # cmd_rasoat_loop chạy hàm THẬT trên dữ liệu thật với max_iter=50 ⇒ gate treo, KHÔNG phải chậm.
    # Vá: gán trên `_TL_MODULE` **VÀ** trên MỌI submodule tl_core đang nạp có thuộc tính đó; hoàn nguyên
    # cả hai. Dùng cho cả 4 khối r255-r258 để không khối nào xanh-oan.
    import sys as _sys261
    _MODS261 = [_m for _n, _m in list(_sys261.modules.items())
                if _n and _n.startswith("tl_core.") and _m is not None]

    def _mp261(save, name, val):
        """Gán `name`=val ở MỌI cửa; ghi lại bản cũ vào `save` để hoàn nguyên."""
        if name not in save:
            save[name] = ([(_TL_MODULE, getattr(_TL_MODULE, name, None))]
                          + [(_m, getattr(_m, name)) for _m in _MODS261 if hasattr(_m, name)])
        setattr(_TL_MODULE, name, val)
        for _m in _MODS261:
            if hasattr(_m, name):
                setattr(_m, name, val)

    def _mpr261(save):
        for _name, _items in save.items():
            for _obj, _old in _items:
                if _old is not None:
                    setattr(_obj, _name, _old)

    # ═══ r255 (v1.35.93) — P15: `rasoat-chongcheo` báo ✗thiếu-corpus cho VBHN ĐÃ CÓ (bare-VBHN chưa nới) ═══
    # 3 điểm so số hiệu của đường chongcheo bỏ sót cổng v1.33.47 (relation-check 681/694 + fetch_web 211 đã có):
    # subject_clusters.json ghi 11/11 số VBHN KHÔNG NĂM, corpus lưu year-qualified ⇒ so exact MISS SẠCH.
    # Đo được: `--base 18/VBHN-VPQH` đẩy CẢ 4 thành viên VBHN của cụm vào unresolved_refs (= giục tải lại
    # văn bản đã có). Và khoá CANONICAL là khoá THẤT BẠI: _cluster_for_base("18-2025-VBHN-VPQH") -> None.
    _E251 = [
        {"drive_id": "d18", "so_hieu": "18-2025-VBHN-VPQH", "name": "BLLD_18-2025-VBHN-VPQH_hop_nhat",
         "loai": "Văn bản hợp nhất", "corpus": "true", "row_kind": "own", "cat": "05_Lao_dong",
         "hieuluc": "Còn hiệu lực"},
        {"drive_id": "d19", "so_hieu": "19-2025-VBHN-VPQH", "name": "Luat_BHXH_19-2025-VBHN-VPQH_hop_nhat",
         "loai": "Văn bản hợp nhất", "corpus": "true", "row_kind": "own", "cat": "05_Lao_dong",
         "hieuluc": "Còn hiệu lực"},
    ]
    # (1) THÀNH VIÊN cụm ghi bare → resolve ra entry year-qualified (trước r255: in_corpus=False)
    _r251a = _resolve_cluster_member("19/VBHN-VPQH", "bảo hiểm xã hội", _E251)
    cases.append(("r255_cluster_member_bare_vbhn_hits_year_qualified",
                  _r251a.get("in_corpus") is True and _r251a.get("drive_id") == "d19"))
    # (2) PHẢN CHỨNG — nới ĐÚNG 1 CHIỀU: query CÓ NĂM vẫn so CHẶT (giữ phân biệt collision theo năm),
    #     không nới sang cơ quan khác, không nới sang số khác, và KHÔNG nới cho số hiệu LUẬT thường.
    cases.append(("r255_no_widen_wrong_year_agency_number",
                  _resolve_cluster_member("19-2024-VBHN-VPQH", "bảo hiểm xã hội", _E251).get("in_corpus") is False
                  and _resolve_cluster_member("19/VBHN-BNV", "bảo hiểm xã hội", _E251).get("in_corpus") is False
                  and _resolve_cluster_member("20/VBHN-VPQH", "bảo hiểm xã hội", _E251).get("in_corpus") is False
                  and _dang_bare_key("74-2025-QH15") == ""))
    # (3) _cluster_for_base: khoá CANONICAL (có năm) tìm ra cụm; số hiệu NGOÀI mọi cụm vẫn ∅ (phản chứng)
    cases.append(("r255_cluster_for_base_year_qualified_and_negative",
                  _cluster_for_base("18-2025-VBHN-VPQH")[0] == "lao_dong_xa_hoi"
                  and _cluster_for_base("18/VBHN-VPQH")[0] == "lao_dong_xa_hoi"        # đường cũ KHÔNG hỏng
                  and _cluster_for_base("999-2025-VBHN-VPQH")[0] is None
                  and _cluster_for_base("")[0] is None))
    # (4) LỆNH THẬT `rasoat-chongcheo`: cụm hết báo thiếu oan, và văn bản THẬT SỰ vắng vẫn còn trong
    #     unresolved_refs (phản chứng chống "vá quá tay làm im mọi cảnh báo").
    # HERMETIC: `target=` đưa cmd_rasoat_chongcheo vào nhánh load_creds + _read_doc_text (lookup_ops L1962)
    # = GỌI MẠNG THẬT khi env có TL_WEBAPP/TL_TOKEN → selftest TREO. Bịt cả hai; nhánh target vẫn được đi qua.
    _sav251 = {}
    try:
        _mp261(_sav251, "_manifest_entries", lambda *_a, **_k: [dict(x) for x in _E251])
        _mp261(_sav251, "apply_profile_offline", lambda *_a, **_k: None)
        _mp261(_sav251, "resolve_footnote_amendments", lambda _t, entries=None: {
            "dieu_level_amendment_map": [{"marker": "1", "dieu": "2", "khoan": "1",
                                          "amending_sohieu": "19/VBHN-VPQH", "hieu_luc": None,
                                          "pending_effect": False, "loai": "sửa đổi"}],
            "footnote_sohieu": [], "header_sohieu": [], "mapped_sohieu": ["19/VBHN-VPQH"], "footnote_count": 1})
        _mp261(_sav251, "_scan_inline_amendments", lambda _t: [])
        _mp261(_sav251, "load_creds", lambda *_a, **_k: None)
        _mp261(_sav251, "_read_doc_text", lambda *_a, **_k: "NGUYEN VAN GIA (offline)")
        _mp261(_sav251, "resolve_identity", lambda *_a, **_k: [])
        _b251 = _hio.StringIO()
        with _hush(), _ctx27.redirect_stdout(_b251):
            _rc251 = _TL_MODULE.cmd_rasoat_chongcheo(argparse.Namespace(
                base="18/VBHN-VPQH", query=None, config=None, profile=None, refresh=False,
                json=True, deterministic=True, text_file=None, target="x", no_auto_footnote=True))
        _o251 = json.loads(_b251.getvalue())
        _ur251 = set(_o251.get("unresolved_refs") or [])
        _row251 = {r.get("sohieu"): r for r in (_o251.get("related") or [])}
        cases.append(("r255_chongcheo_vbhn_members_not_reported_missing",
                      _rc251 == 0
                      and "19/VBHN-VPQH" not in _ur251                        # cụm + footnote: ĐÃ CÓ corpus
                      and _row251.get("19/VBHN-VPQH", {}).get("in_corpus") is True
                      and "74/2025/QH15" in _ur251                            # PHẢN CHỨNG: vắng thật vẫn báo
                      and "14/VBHN-VPQH" in _ur251))                          # PHẢN CHỨNG: VBHN vắng thật vẫn báo
    except Exception:
        cases.append(("r255_chongcheo_vbhn_members_not_reported_missing", False))
    finally:
        _mpr261(_sav251)


    # ═══ r256 (v1.35.94) — P15: `rasoat-loop` DỪNG SỚM, báo THIẾU gap (dry_rounds nằm trong ĐK vòng) ═══
    # `while frontier and dry_rounds < K and it < max_iter` — chạm K là thoát DÙ frontier còn; và ứng viên
    # NGOÀI corpus cũng dry_rounds++ ⇒ càng tìm ra nhiều GAP càng dừng sớm. Đo được: 5 ứng viên ngoài corpus,
    # K=2 → báo 2/5 GAP, frontier_remaining=3, mà max_iter=12 CHƯA HỀ chạm; thông điệp lại nói "chạm max-iter".
    def _r255_run(cands, K=2, max_iter=12, expand2=None):
        """Chạy cmd_rasoat_loop offline: seed = `cands`, lượt expand sau trả `expand2` (mặc định rỗng)."""
        _keys = ("_manifest_entries", "apply_profile_offline", "_frontier_doc_text",
                 "_rasoat_expand_text", "_resolve_deep_target", "_read_doc_text")
        _sav = {}
        _n = {"i": 0}
        try:
            _mp261(_sav, "_manifest_entries", lambda *_a, **_k: [])
            _mp261(_sav, "apply_profile_offline", lambda *_a, **_k: None)
            _mp261(_sav, "_frontier_doc_text", lambda _a: ("BASE TEXT", "gid0", "BASE"))

            def _exp(_t, _e):
                _n["i"] += 1
                return list(cands) if _n["i"] == 1 else list(expand2 or [])
            _mp261(_sav, "_rasoat_expand_text", _exp)
            _mp261(_sav, "_resolve_deep_target", lambda *_a, **_k: (None, None, None, None))
            _mp261(_sav, "_read_doc_text", lambda *_a, **_k: "")
            _b = _hio.StringIO()
            with _hush(), _ctx27.redirect_stdout(_b):
                _rc = _TL_MODULE.cmd_rasoat_loop(argparse.Namespace(
                    config=None, profile=None, refresh=False, json=True, deterministic=True,
                    dry_rounds=K, max_iter=max_iter, text_file=None, target="x"))
            return _rc, json.loads(_b.getvalue())
        finally:
            _mpr261(_sav)

    def _r255_gaps(n):
        return [{"sohieu": "%d/2020/QH14" % i, "sohieu_norm": norm_sohieu("%d/2020/QH14" % i),
                 "in_corpus": False, "priority": 1} for i in range(1, n + 1)]

    # (1) 5 ứng viên ngoài corpus: PHẢI vét hết frontier và báo ĐỦ 5 GAP (trước r256: 2/5, còn dư 3)
    _rc252, _o252 = _r255_run(_r255_gaps(5))
    cases.append(("r256_loop_drains_frontier_reports_all_gaps",
                  _rc252 == 0 and _o252.get("frontier_remaining") == 0
                  and len(_o252.get("gaps_missing_in_corpus") or []) == 5
                  and _o252.get("evaluated") == 5
                  and _o252.get("stop_reason") == "frontier_empty"
                  and _o252.get("converged") is True))
    # (2) PHẢN CHỨNG — max_iter VẪN là trần cứng, KHÔNG bị bản vá nới: 20 ứng viên, max_iter=3
    _rc252b, _o252b = _r255_run(_r255_gaps(20), K=2, max_iter=3)
    cases.append(("r256_max_iter_still_hard_ceiling",
                  _o252b.get("iterations") == 3 and _o252b.get("frontier_remaining") == 17
                  and _o252b.get("stop_reason") == "max_iter"
                  and _o252b.get("converged") is False
                  and len(_o252b.get("gaps_missing_in_corpus") or []) == 3))
    # (3) PHẢN CHỨNG — dry_rounds GIỮ vai trò tín hiệu hội tụ, KHÔNG bị vô hiệu hoá:
    #     1 ứng viên duy nhất, frontier cạn nhưng dry_rounds=1 < K=2 ⇒ converged=False (không tự nhận hội tụ)
    _rc252c, _o252c = _r255_run(_r255_gaps(1), K=2)
    cases.append(("r256_dry_rounds_still_gates_converged",
                  _o252c.get("frontier_remaining") == 0 and _o252c.get("dry_rounds") == 1
                  and _o252c.get("stop_reason") == "frontier_empty"
                  and _o252c.get("converged") is False))
    # (4) PHẢN CHỨNG — KHÔNG lặp vô hạn khi expand cứ trả ứng viên: `seen` vẫn chặn, trần max_iter vẫn cắt.
    _rc252d, _o252d = _r255_run(_r255_gaps(2) + [{"sohieu": "9/2020/QH14", "sohieu_norm": norm_sohieu("9/2020/QH14"),
                                                  "in_corpus": True, "priority": 1}],
                                K=2, max_iter=50, expand2=_r255_gaps(2))
    cases.append(("r256_no_infinite_loop_seen_dedup_holds",
                  _rc252d == 0 and _o252d.get("iterations") <= 3
                  and _o252d.get("seen") == 3 and _o252d.get("frontier_remaining") == 0))

    # ═══ r295 (v1.36.32) — T1-c Làn A: MỘT định nghĩa hội tụ (RAS-04 + RAS-10, audit lõi 31-07) ═══
    # ★ ĐỔI SỐ khi land (01-08): khối này ra đời mang mã `r291_*`/`r290/T1-c`, nhưng CẢ HAI số đã bị
    #   chiếm bởi bản land trước (r291 = `docs/` ra khỏi gói/T0-G · r290 = rasoat-merge fail-CLOSED),
    #   nên CẢ HAI nửa T1-c (vòng rà + state, mã cũ `r291_*`/`r293_*`) được gom về MỘT mã `r295`.
    #   Biến cục bộ nửa state còn giữ hậu tố `293` (vd `_rc293c`) — cố ý không đổi: chúng là tên cục bộ
    #   trong `run()`, không phải mã ca, và đổi thêm chỉ làm nhiễu diff mà không thêm thông tin.
    # Đặt NGAY SAU r255/r256 vì cùng đối tượng và dùng chung khuôn `_r255_run` — `_mp261` vá Ở MỌI CỬA
    # (tl + mọi module giữ bản sao globals), khác hẳn setattr trần chỉ vá một cửa.
    # RAS-04 và RAS-10 nhìn thì ngược nhau (một bên đòi lỗi KHÔNG được tính là hội tụ, bên kia đòi
    # frontier-rỗng-từ-đầu PHẢI là hội tụ) — thực ra là hai vế của MỘT định nghĩa:
    #     converged = frontier cạn ∧ khong_doc_duoc = 0 ∧ (dry_rounds ≥ K ∨ chưa từng có ứng viên nào)
    # A/B trên cây HEAD trước khi vá: hai lỗi đọc ⇒ dry_rounds=2 chạm K ⇒ **converged:true, rc=0**, tức
    # lệnh tuyên bố "đã soi hết" trong khi chưa hề nhìn vào hai văn bản; frontier rỗng từ đầu ⇒
    # **converged:false** vĩnh viễn vì dry_rounds=0 < K.
    def _r295_run(cands, K=2, max_iter=12, doc_loi=False):
        """Như `_r255_run` nhưng ứng viên IN-CORPUS có gid THẬT, và đường đọc có thể ném lỗi."""
        _sav, _n = {}, {"i": 0}
        try:
            _mp261(_sav, "_manifest_entries", lambda *_a, **_k: [])
            _mp261(_sav, "apply_profile_offline", lambda *_a, **_k: None)
            _mp261(_sav, "_entry_on_nlm_live", lambda _e: True)
            _mp261(_sav, "_frontier_doc_text", lambda _a: ("BASE TEXT", "gid0", "BASE"))

            def _exp295(_t, _e):
                _n["i"] += 1
                return list(cands) if _n["i"] == 1 else []
            _mp261(_sav, "_rasoat_expand_text", _exp295)
            _mp261(_sav, "_resolve_deep_target", lambda _sh, *_a, **_k: (None, "gid-" + str(_sh), None, None))

            def _read295(*_a, **_k):
                if doc_loi:
                    raise RuntimeError("gws chet")
                return "RUOT VAN BAN"
            _mp261(_sav, "_read_doc_text", _read295)
            _b = _hio.StringIO()
            with _hush(), _ctx27.redirect_stdout(_b):
                _rc = _TL_MODULE.cmd_rasoat_loop(argparse.Namespace(
                    config=None, profile=None, refresh=False, json=True, deterministic=True,
                    dry_rounds=K, max_iter=max_iter, text_file=None, target="x"))
            return _rc, json.loads(_b.getvalue())
        finally:
            _mpr261(_sav)

    _CAND295 = [{"sohieu": "10/2020/ND-CP", "sohieu_norm": norm_sohieu("10/2020/ND-CP"),
                 "in_corpus": True, "priority": 1},
                {"sohieu": "11/2020/ND-CP", "sohieu_norm": norm_sohieu("11/2020/ND-CP"),
                 "in_corpus": True, "priority": 1}]

    # RAS-04: lỗi đọc vào sổ RIÊNG `khong_doc_duoc`, KHÔNG đụng `dry_rounds`, và CHẶN hội tụ + rc≠0
    _rc295a, _o295a = _r295_run(_CAND295, doc_loi=True)
    cases.append(("r295_loi_doc_khong_thanh_hoi_tu",
                  _rc295a == 2 and _o295a.get("converged") is False and _o295a.get("ok") is False
                  and _o295a.get("dry_rounds") == 0
                  and len(_o295a.get("khong_doc_duoc") or []) == 2))
    # RAS-10: base không dẫn đi đâu ⇒ HỘI TỤ THẬT, có `stop_reason` riêng để không chẩn đoán nhầm
    _rc295b, _o295b = _r295_run([])
    cases.append(("r295_frontier_rong_tu_dau_la_hoi_tu",
                  _rc295b == 0 and _o295b.get("converged") is True
                  and _o295b.get("stop_reason") == "frontier_empty_ngay_tu_dau"
                  and _o295b.get("dry_rounds") == 0))
    # ★ PHẢN CHỨNG chống siết-quá-tay: đọc ĐƯỢC mà không sinh ứng viên mới ⇒ vẫn hội tụ, rc=0 y như cũ
    _rc295c, _o295c = _r295_run(_CAND295)
    cases.append(("r295_doc_duoc_van_hoi_tu_nhu_cu",
                  _rc295c == 0 and _o295c.get("converged") is True and _o295c.get("ok") is True
                  and _o295c.get("dry_rounds") == 2 and (_o295c.get("khong_doc_duoc") or []) == []))
    # ★ PHẢN CHỨNG RANH GIỚI (bắt được nhờ r256 đỏ): ứng viên IN-CORPUS mà KHÔNG giải được GDoc id là
    #   sổ KHÁC — chỉ BÁO, KHÔNG chặn hội tụ, KHÔNG đổi rc. Gộp hai sổ làm đỏ
    #   `r256_no_infinite_loop_seen_dedup_holds` và siết quá phạm vi RAS-04 (nói về `_read_doc_text`).
    _sav295, _n295 = {}, {"i": 0}
    try:
        _mp261(_sav295, "_manifest_entries", lambda *_a, **_k: [])
        _mp261(_sav295, "apply_profile_offline", lambda *_a, **_k: None)
        _mp261(_sav295, "_entry_on_nlm_live", lambda _e: True)
        _mp261(_sav295, "_frontier_doc_text", lambda _a: ("BASE TEXT", "gid0", "BASE"))

        def _exp295b(_t, _e):
            _n295["i"] += 1
            return list(_CAND295) if _n295["i"] == 1 else []
        _mp261(_sav295, "_rasoat_expand_text", _exp295b)
        _mp261(_sav295, "_resolve_deep_target", lambda *_a, **_k: (None, None, None, None))
        _mp261(_sav295, "_read_doc_text", lambda *_a, **_k: "")
        _b295 = _hio.StringIO()
        with _hush(), _ctx27.redirect_stdout(_b295):
            _rc295d = _TL_MODULE.cmd_rasoat_loop(argparse.Namespace(
                config=None, profile=None, refresh=False, json=True, deterministic=True,
                dry_rounds=2, max_iter=12, text_file=None, target="x"))
        _o295d = json.loads(_b295.getvalue())
    finally:
        _mpr261(_sav295)
    cases.append(("r295_khong_co_ban_doc_chi_bao_khong_chan_hoi_tu",
                  _rc295d == 0 and _o295d.get("converged") is True
                  and (_o295d.get("khong_doc_duoc") or []) == []
                  and len(_o295d.get("khong_co_ban_doc") or []) == 2))

    # ═══ r295 (tiếp) — RAS-13: "có trong corpus" phải là CORPUS-HIỆU-LỰC ═══
    # Trước vá, `rasoat-chongcheo` so số hiệu trên TOÀN `entries` nên dòng đã hạ `corpus=false`, dòng
